  '<kbd>↑</kbd><kbd>↓</kbd> move': '<kbd>↑</kbd><kbd>↓</kbd> se déplacer', '<kbd>Enter</kbd> open': '<kbd>Entrée</kbd> ouvrir', '<kbd>Ctrl</kbd>+<kbd>K</kbd> anywhere': '<kbd>Ctrl</kbd>+<kbd>K</kbd> partout',
